/**
 * FXC HLSL Compiler website.
 * Uses retrowin32 WASM to run d3d_compile.exe (which calls D3DCOMPILER_43.dll).
 * Place d3d_compile.exe and D3DCOMPILER_43.dll in the same directory as this page,
 * or configure their paths via URL params: ?exe=path/to/d3d_compile.exe&dll=path/to/D3DCOMPILER_43.dll
 */

import * as wasm from './glue/pkg/glue';

// Monaco is loaded from CDN via the AMD loader in the HTML.
declare const require: ((deps: string[], cb: () => void) => void) & { config(o: any): void };
declare const monaco: any;

const DEFAULT_HLSL = `float4 main(float2 uv : TEXCOORD) : SV_Target {
    float3 color = float3(uv.x, uv.y, 0.5);
    return float4(color, 1.0);
}
`;

// --- Permalink helpers (gzip + base64url, matches C# GZipStream + base64url) ---

async function compressCode(code: string): Promise<string> {
  const bytes = new TextEncoder().encode(code);
  const cs = new CompressionStream('gzip');
  const writer = cs.writable.getWriter();
  writer.write(bytes);
  writer.close();
  const chunks: Uint8Array[] = [];
  const reader = cs.readable.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value as Uint8Array);
  }
  const total = chunks.reduce((n, c) => n + c.length, 0);
  const buf = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) { buf.set(c, offset); offset += c.length; }
  let binary = '';
  for (let i = 0; i < buf.length; i++) binary += String.fromCharCode(buf[i]);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function decompressCode(encoded: string): Promise<string> {
  encoded = encoded.replace(/-/g, '+').replace(/_/g, '/');
  while (encoded.length % 4) encoded += '=';
  const binary = atob(encoded);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  const ds = new DecompressionStream('gzip');
  const writer = ds.writable.getWriter();
  writer.write(bytes);
  writer.close();
  const chunks: Uint8Array[] = [];
  const reader = ds.readable.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value as Uint8Array);
  }
  const total = chunks.reduce((n, c) => n + c.length, 0);
  const buf = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) { buf.set(c, offset); offset += c.length; }
  return new TextDecoder().decode(buf);
}

// --- File implementation for the emulator's virtual filesystem ---

class FxcFile implements wasm.JsFile {
  private ofs = 0;
  constructor(private bytes: Uint8Array) {}

  info(): number { return this.bytes.length; }

  seek(from: number, ofs: number): number {
    if (from === 0) this.ofs = ofs;
    else if (from === 1) this.ofs = this.bytes.length + ofs;
    else this.ofs += ofs; // from === 2
    if (this.ofs < 0) this.ofs = 0;
    if (this.ofs > this.bytes.length) this.ofs = this.bytes.length;
    return this.ofs;
  }

  read(buf: Uint8Array): number {
    const n = Math.min(buf.length, this.bytes.length - this.ofs);
    buf.set(this.bytes.subarray(this.ofs, this.ofs + n));
    this.ofs += n;
    return n;
  }

  write(_buf: Uint8Array): number { return _buf.length; }
}

// --- Host implementation ---

interface FileSet {
  [key: string]: Uint8Array;
}

class FxcHost implements wasm.JsHost {
  private stdinBytes: Uint8Array;
  private stdinPos = 0;
  private decoder = new TextDecoder();
  output = '';

  constructor(
    private files: FileSet,
    hlsl: string,
  ) {
    this.stdinBytes = new TextEncoder().encode(hlsl);
  }

  log(level: number, msg: string) {
    if (level === 1) {
      this.output += '[error] ' + msg + '\n';
      console.error(msg);
    } else {
      console.warn(msg);
    }
  }

  win32_trace(_context: string, _msg: string) {}

  ensure_timer(_when: number) {}

  get_event(): Event { return undefined as any; }

  stdin(buf: Uint8Array): number {
    const remaining = this.stdinBytes.length - this.stdinPos;
    if (remaining <= 0) return 0; // EOF
    const n = Math.min(buf.length, remaining);
    buf.set(this.stdinBytes.subarray(this.stdinPos, this.stdinPos + n));
    this.stdinPos += n;
    return n;
  }

  stdout(buf: Uint8Array) {
    this.output += this.decoder.decode(buf, { stream: true });
  }

  flushOutput() {
    this.output += this.decoder.decode(); // flush any held-back bytes
  }

  open(path: string, options: wasm.FileOptions): wasm.JsFile | null {
    if (options.create) return new FxcFile(new Uint8Array());
    // Try the full path, then just the basename (case-insensitive).
    const key = path.toLowerCase().replace(/\\/g, '/');
    const basename = key.split('/').pop()!;
    const bytes = this.files[basename] ?? this.files[key];
    return bytes ? new FxcFile(bytes) : null;
  }

  create_window(_hwnd: number): wasm.JsWindow { throw new Error('no window support'); }
  screen(): CanvasRenderingContext2D { throw new Error('no screen support'); }
  audio(_buf: Int16Array) {}
}

// --- Syntax highlighter (replicates FXC /Cc color scheme) ---

function escapeHtml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function highlightAsm(text: string): string {
  // Normalize Windows line endings
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  return lines.map(line => {
    const trimmed = line.trimStart();

    // Comment lines
    if (trimmed.startsWith('//') || trimmed === '') {
      return `<span class="asm-comment">${escapeHtml(line)}</span>`;
    }

    // Strip HTML comment instruction IDs that D3DDisassemble sometimes emits
    let working = line.replace(/<!--[^>]*-->/g, '');

    // Escape HTML in the working line
    working = escapeHtml(working);

    // Highlight numeric literals: l(...)
    working = working.replace(
      /\bl(\([^)]*\))/g,
      (_, args) => `<span class="asm-lit">l${args}</span>`,
    );

    // Highlight the leading opcode/declaration keyword
    working = working.replace(
      /^(\s*)([a-z][a-z0-9_]*)/,
      (_, ws, kw) => `${ws}<span class="asm-op">${kw}</span>`,
    );

    return working;
  }).join('\n');
}

// --- Diagnostic highlighting and parsing ---

function highlightDiagnosticLines(text: string): string {
  return text.replace(/\r\n/g, '\n').split('\n').map(line => {
    if (/\)\s*:\s*warning\s/.test(line))
      return `<span class="asm-warning">${escapeHtml(line)}</span>`;
    if (/\)\s*:\s*error\s/.test(line))
      return `<span class="asm-error">${escapeHtml(line)}</span>`;
    return highlightAsm(line);
  }).join('\n');
}

interface Diagnostic {
  line: number;
  startCol: number;
  endCol: number;
  severity: 'warning' | 'error';
  message: string;
}

function parseDiagnostics(text: string): Diagnostic[] {
  const diags: Diagnostic[] = [];
  // FXC format: path(line,startCol[-endCol]): warning|error Xnnnn: message
  const re = /\((\d+),(\d+)(?:-(\d+))?\)\s*:\s*(warning|error)\s+\w+:\s*(.+)$/gm;
  let m;
  while ((m = re.exec(text)) !== null) {
    const startCol = parseInt(m[2], 10);
    const endCol = m[3] ? parseInt(m[3], 10) : startCol + 1;
    diags.push({
      line: parseInt(m[1], 10),
      startCol,
      endCol: Math.max(endCol, startCol + 1),
      severity: m[4] as 'warning' | 'error',
      message: m[5].trim(),
    });
  }
  return diags;
}

// --- Emulator runner ---

async function compile(
  files: FileSet,
  hlsl: string,
  profile: string,
  entry: string,
  optLevel: number,
): Promise<string> {
  const host = new FxcHost(files, hlsl);
  const emu = wasm.new_emulator(host as any);
  try {
    emu.set_external_dlls(['d3dcompiler_47.dll', 'D3DCOMPILER_47.dll', 'd3dcompiler_43.dll', 'D3DCOMPILER_43.dll']);
    emu.start_exe(`d3d_compile.exe ${profile} ${entry} ${optLevel} 1`, false);

    // Run asynchronously in batches to not block the UI thread.
    await new Promise<void>((resolve, reject) => {
      const ch = new MessageChannel();
      ch.port2.onmessage = () => {
        emu.unblock();
        let status: wasm.Status;
        try {
          status = emu.run(1_000_000) as wasm.Status;
        } catch (e: any) {
          host.flushOutput();
          const wasmMsg = e?.message ?? String(e);
          const detail = host.output ? `${host.output}\n[wasm] ${wasmMsg}` : wasmMsg;
          reject(new Error(detail));
          return;
        }
        switch (status) {
          case wasm.Status.Running:
          case wasm.Status.Blocked:
            ch.port1.postMessage(null);
            break;
          case wasm.Status.Exit:
            host.flushOutput();
            resolve();
            break;
          default:
            reject(new Error(`emulator stopped unexpectedly: ${status}`));
        }
      };
      ch.port1.postMessage(null);
    });
  } finally {
    emu.free();
  }

  return host.output;
}

